INSERT INTO writing_pieces
(id, owner_id, slug, title, subtitle, type, status, visibility, excerpt,
 structured_content, cover_image_id, created_at, updated_at, published_at,
 archived_at, show_origin, source_conversation_id)
VALUES (
  'wrt_63cdb0c4335f3fa8bac665adfb20c1db','usr_ffbc49c36dc84f0889dfb5de2f68ccc3','that-flowers-fall-sonnet','That flowers fall','Original sonnet and reflection from high school','poem','public','public',
  'Does Nature not die certain as shall I? As Nature is beauty, I am alive.','{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "That flowers fall"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "High-school original Shakespearean sonnet (with a short craft reflection) for AP Literature — on mortality, nature, and being alive.", "marks": [{"type": "italic"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "That flowers fall"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Like autumn comes and leaves begin to blush"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Like rains confess the wild’s restraining souls"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Screams the rowdy youth of such fragile rush"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Roars our untamed minds from London to Seoul"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Speak love, speak hate and He may laugh at thee"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "At crazed and blinded fixations like fame"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "But though He sings slow ballads to the sea"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "So does He mourn unruly souls like Cain"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "And look, oh look, that flowers fall as well"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "and blushing leaves shower idlers in fall"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Like wind lies, like rain dies, like waves shall swell"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Like flowers fall, like me, all things befall"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Does Nature not die certain as shall I?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "As Nature is beauty, I am alive."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Reflection"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "I initially came up with the thematic topic of the poem with the inspiration of Seventeen’s “Fallin’ Flower”, which is a song about the beautiful yet almost melancholic nature of a flower, metaphorically comparing the fall of a flower to falling in love. While I do not speak Japanese, I mostly understood the song through the instrumentals and the melancholic tone, which inspired me to also write a nature based poem. Instead of love, I decided to focus more on the awe of existing, relating to both the falling of flowers and leaves as well as the beauty of the fall season that we are currently experiencing. As an appreciative reader of Shakespearean sonnets, I decided upon writing a Shakespearean sonnet with an iambic pentameter, mostly due to the simple nature of the meter and rhyme that helps reflect the simple yet elegant metaphor that I intended to describe in my poem. Also as a fond reader of classic books, I sprinkled in a few religiously connotated mentions, like the implication that God is looking out for man as much as nature through “mourn souls as unruly as Cain”. This I found to be precisely what was needed to convert the similarity between nature and humans, because it helped convey that since God created us all, we are all valuable and fragile creations by the same artist. Additionally, I found that old English was a great way to cut back on the number of syllables as well as rhyming needed to convey the same message, alas the “laugh at thee” and “Does nature not die certain as shall I?”. While my first draft did take a couple trials, most of them are changes with wording so as to more clearly describe how similar nature is to humans. Initial trials took a more contemplative approach towards nature and tying it to both religion and prayers, but I later found that this approach took away from the intimacy of the comparison between humans and nature as it would simultaneously require humans to be described in a similarly mystical way. Throughout the process, the most trouble that I had was with the last two lines after the volta, since the focus was really on concluding the comparison and bringing the thought back to myself. I found that 20 syllables was not quite enough to put all that I wanted to conclude with the metaphor between humans and nature, so it took quite a bit of rewording and cutting to result in what is now the last two lines of the poem. In the end, I decided to pay yet another homage to Shakespeare to take his idea for a rhetorical question, because I found that it better establishes the contemplative theme of the poem, and helps lead to the last conclusion that compares myself specifically to nature. My revised sonnet is not really different from my first draft because I found that my draft does successfully convey the message that I wished for it to convey. A few minor edits were made to make sure that the syllabic count is the same for each line and the necessary rewording was completed in order for that to be achieved."}]}]}',NULL,1785481355305,1785481355305,1785481355305,NULL,0,NULL
);
INSERT INTO writing_versions (id, writing_id, structured_content_snapshot, title_snapshot, source, created_at)
VALUES ('wver_23ca310215583aa9df995960','wrt_63cdb0c4335f3fa8bac665adfb20c1db','{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "That flowers fall"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "High-school original Shakespearean sonnet (with a short craft reflection) for AP Literature — on mortality, nature, and being alive.", "marks": [{"type": "italic"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "That flowers fall"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Like autumn comes and leaves begin to blush"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Like rains confess the wild’s restraining souls"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Screams the rowdy youth of such fragile rush"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Roars our untamed minds from London to Seoul"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Speak love, speak hate and He may laugh at thee"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "At crazed and blinded fixations like fame"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "But though He sings slow ballads to the sea"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "So does He mourn unruly souls like Cain"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "And look, oh look, that flowers fall as well"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "and blushing leaves shower idlers in fall"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Like wind lies, like rain dies, like waves shall swell"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Like flowers fall, like me, all things befall"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Does Nature not die certain as shall I?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "As Nature is beauty, I am alive."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Reflection"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "I initially came up with the thematic topic of the poem with the inspiration of Seventeen’s “Fallin’ Flower”, which is a song about the beautiful yet almost melancholic nature of a flower, metaphorically comparing the fall of a flower to falling in love. While I do not speak Japanese, I mostly understood the song through the instrumentals and the melancholic tone, which inspired me to also write a nature based poem. Instead of love, I decided to focus more on the awe of existing, relating to both the falling of flowers and leaves as well as the beauty of the fall season that we are currently experiencing. As an appreciative reader of Shakespearean sonnets, I decided upon writing a Shakespearean sonnet with an iambic pentameter, mostly due to the simple nature of the meter and rhyme that helps reflect the simple yet elegant metaphor that I intended to describe in my poem. Also as a fond reader of classic books, I sprinkled in a few religiously connotated mentions, like the implication that God is looking out for man as much as nature through “mourn souls as unruly as Cain”. This I found to be precisely what was needed to convert the similarity between nature and humans, because it helped convey that since God created us all, we are all valuable and fragile creations by the same artist. Additionally, I found that old English was a great way to cut back on the number of syllables as well as rhyming needed to convey the same message, alas the “laugh at thee” and “Does nature not die certain as shall I?”. While my first draft did take a couple trials, most of them are changes with wording so as to more clearly describe how similar nature is to humans. Initial trials took a more contemplative approach towards nature and tying it to both religion and prayers, but I later found that this approach took away from the intimacy of the comparison between humans and nature as it would simultaneously require humans to be described in a similarly mystical way. Throughout the process, the most trouble that I had was with the last two lines after the volta, since the focus was really on concluding the comparison and bringing the thought back to myself. I found that 20 syllables was not quite enough to put all that I wanted to conclude with the metaphor between humans and nature, so it took quite a bit of rewording and cutting to result in what is now the last two lines of the poem. In the end, I decided to pay yet another homage to Shakespeare to take his idea for a rhetorical question, because I found that it better establishes the contemplative theme of the poem, and helps lead to the last conclusion that compares myself specifically to nature. My revised sonnet is not really different from my first draft because I found that my draft does successfully convey the message that I wished for it to convey. A few minor edits were made to make sure that the syllabic count is the same for each line and the necessary rewording was completed in order for that to be achieved."}]}]}','That flowers fall','seed',1785481355305);
DELETE FROM writing_pieces WHERE slug = 'i-quit-narrative';
INSERT INTO writing_pieces
(id, owner_id, slug, title, subtitle, type, status, visibility, excerpt,
 structured_content, cover_image_id, created_at, updated_at, published_at,
 archived_at, show_origin, source_conversation_id)
VALUES (
  'wrt_ead24461bcbd2bce8c24d40599c049f4','usr_ffbc49c36dc84f0889dfb5de2f68ccc3','i-quit-narrative','I quit','Personal narrative from high school','essay','public','public',
  'Am I more American or Chinese? Both.','{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "I quit"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "High-school personal narrative about moving from China to the U.S., national anthems, allegiance, and refusing to choose only one identity.", "marks": [{"type": "italic"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Perhaps you’ve never heard of the chinese national anthem before. With a passionate swing of the voice, each note screams the pride of its people, the vibrance of its youth, the virtue of its soldiers, “Arise! Arise! Arise!” That was the sound of a song sung in unity, a sound, almost like an alarm, that went off every Monday morning when the school gathered to watch the flag rise."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "I was born in a small city in the People’s Republic of China, a city with beauty but no fame, culture but no uniqueness, a vessel drained of its former glory. Growing up, I never understood what it meant exactly to be chinese. I have never met someone who was not, and frankly, I would quite easily mistake Africa for a country, if only I knew where that was on a map. But fate has always been the greatest of magicians, and fast forward a few years, I stepped onto a land foreign to me all but in name. The United States of America."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "I was in fourth grade when I was introduced to this foreign world with foreign ideals, from singing “March of the Volunteers'''', I had to do the pledge of allegiance, had to sing the “Star Spangled Banner'''', and had to introduce to a school of mostly causasian students what life was like in a foreign country. My country. Yet I was never more proud of being “different” and of being able to identify as Chinese. Like a black pen against a white background, I have never felt so visible and so glad of my differences for making me seen. Where are you from? I’m from China. And you can instantly see a face of curiosity and accomplishment of someone who finally succeeded to get a conversation started. Can you say something in chinese? Sure. Can you teach me something? No problem. There was always a sentence starter for an awkward and boring conversation."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“Bang!” was the sound of an intense discussion bordering the edge of an argument. It’s hands flailing in the air, words echoing down the hall; it''s walking back and forth, pointlessly, until you make some crucial argument. It’s dinner time, but I was the only one sitting, the others were either participating in the discussion or are intently listening to it. My mind starts to drift away."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Perhaps it was middle school social studies, or it was the presidential election of 2016. I began to recall the gradual isolation of a kid whose education no longer aligned with her friends’ in China, whose identity began to waver, and whose combination of knowledge became ever more confusing to her. I recall that year, the trade war between China and the U.S., when the first dose of confusion rushed down her as she was fed different knowledge from her teachers and her parents. I recall the year when she became an American citizen, and for the first time in her life, she lost sight of the kid standing and singing, “Arise! Arise! Arise!”"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“I don’t know if I am more American or more Chinese”, she complained, out of frustration. “Both,” said her chinese american friend who shared her identity, but not her experiences."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The debate has gotten louder down the hall; my dad and grandpa have now made a complete lap around the house and are now starting round two. From Trump’s policies they have moved on to the 2020 election. From the treatment of asian americans they have moved on to international relations. No one, yet everyone, seems to have taken part of my mental turmoil."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The day in english class when her teacher asked the class to name the biggest villains in history. Up on the board, a list of names had already congregated- Hitler, Robespierre, Stalin… and Mao Zedong. It was strange to hear a name so familiar to you listed in an unfamiliar way. The founder of her country, the pride of her people, the face of the people’s republic of china. The villain. She felt conflicted having now knowledge she didn’t know what to do with. Maybe she shed a few tears, but more of bewilderment than in true sadness. She couldn’t help but confide in her mom the incident in class that day. Her mom looked at her, almost careless in reply, “This is politics. It''s not a matter of people or events, it''s a matter of how they are portrayed…”"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "I shrug a little. Some time during the argument a political debate had turned personal, and my always patriotic grandfather began to give a passionate speech of his values and his beliefs. Each word screams the pride of his people, the vibrance of his youth, the virtue of his soldier friends whom he knows well. The last sentence that I had cared to listen to from that argument was this, and it was addressed to me specifically, “Even though you are American, I still love you, and I hope that you remember your roots.”"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "At that precise moment I recalled the chinese child singing her national anthem, the american child citing her pledge of allegiance, and the lost soul being perplexed by two identities ripping her apart and threatening to create a rift between her family. Somehow none of that no matter matters. Her and I are no longer the same person, or perhaps we have always been. As I truly left behind my confusion and frustration in the face of politics and picking a side, I gave myself a way out, which is to no longer care about politics."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Am I more American or Chinese? Both."}]}]}',NULL,1785481355305,1785481355305,1785481355305,NULL,0,NULL
);
INSERT INTO writing_versions (id, writing_id, structured_content_snapshot, title_snapshot, source, created_at)
VALUES ('wver_7cebc4d7e92cc50589ce2e5e','wrt_ead24461bcbd2bce8c24d40599c049f4','{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "I quit"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "High-school personal narrative about moving from China to the U.S., national anthems, allegiance, and refusing to choose only one identity.", "marks": [{"type": "italic"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Perhaps you’ve never heard of the chinese national anthem before. With a passionate swing of the voice, each note screams the pride of its people, the vibrance of its youth, the virtue of its soldiers, “Arise! Arise! Arise!” That was the sound of a song sung in unity, a sound, almost like an alarm, that went off every Monday morning when the school gathered to watch the flag rise."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "I was born in a small city in the People’s Republic of China, a city with beauty but no fame, culture but no uniqueness, a vessel drained of its former glory. Growing up, I never understood what it meant exactly to be chinese. I have never met someone who was not, and frankly, I would quite easily mistake Africa for a country, if only I knew where that was on a map. But fate has always been the greatest of magicians, and fast forward a few years, I stepped onto a land foreign to me all but in name. The United States of America."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "I was in fourth grade when I was introduced to this foreign world with foreign ideals, from singing “March of the Volunteers'''', I had to do the pledge of allegiance, had to sing the “Star Spangled Banner'''', and had to introduce to a school of mostly causasian students what life was like in a foreign country. My country. Yet I was never more proud of being “different” and of being able to identify as Chinese. Like a black pen against a white background, I have never felt so visible and so glad of my differences for making me seen. Where are you from? I’m from China. And you can instantly see a face of curiosity and accomplishment of someone who finally succeeded to get a conversation started. Can you say something in chinese? Sure. Can you teach me something? No problem. There was always a sentence starter for an awkward and boring conversation."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“Bang!” was the sound of an intense discussion bordering the edge of an argument. It’s hands flailing in the air, words echoing down the hall; it''s walking back and forth, pointlessly, until you make some crucial argument. It’s dinner time, but I was the only one sitting, the others were either participating in the discussion or are intently listening to it. My mind starts to drift away."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Perhaps it was middle school social studies, or it was the presidential election of 2016. I began to recall the gradual isolation of a kid whose education no longer aligned with her friends’ in China, whose identity began to waver, and whose combination of knowledge became ever more confusing to her. I recall that year, the trade war between China and the U.S., when the first dose of confusion rushed down her as she was fed different knowledge from her teachers and her parents. I recall the year when she became an American citizen, and for the first time in her life, she lost sight of the kid standing and singing, “Arise! Arise! Arise!”"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“I don’t know if I am more American or more Chinese”, she complained, out of frustration. “Both,” said her chinese american friend who shared her identity, but not her experiences."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The debate has gotten louder down the hall; my dad and grandpa have now made a complete lap around the house and are now starting round two. From Trump’s policies they have moved on to the 2020 election. From the treatment of asian americans they have moved on to international relations. No one, yet everyone, seems to have taken part of my mental turmoil."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The day in english class when her teacher asked the class to name the biggest villains in history. Up on the board, a list of names had already congregated- Hitler, Robespierre, Stalin… and Mao Zedong. It was strange to hear a name so familiar to you listed in an unfamiliar way. The founder of her country, the pride of her people, the face of the people’s republic of china. The villain. She felt conflicted having now knowledge she didn’t know what to do with. Maybe she shed a few tears, but more of bewilderment than in true sadness. She couldn’t help but confide in her mom the incident in class that day. Her mom looked at her, almost careless in reply, “This is politics. It''s not a matter of people or events, it''s a matter of how they are portrayed…”"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "I shrug a little. Some time during the argument a political debate had turned personal, and my always patriotic grandfather began to give a passionate speech of his values and his beliefs. Each word screams the pride of his people, the vibrance of his youth, the virtue of his soldier friends whom he knows well. The last sentence that I had cared to listen to from that argument was this, and it was addressed to me specifically, “Even though you are American, I still love you, and I hope that you remember your roots.”"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "At that precise moment I recalled the chinese child singing her national anthem, the american child citing her pledge of allegiance, and the lost soul being perplexed by two identities ripping her apart and threatening to create a rift between her family. Somehow none of that no matter matters. Her and I are no longer the same person, or perhaps we have always been. As I truly left behind my confusion and frustration in the face of politics and picking a side, I gave myself a way out, which is to no longer care about politics."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Am I more American or Chinese? Both."}]}]}','I quit','seed',1785481355305);
DELETE FROM writing_pieces WHERE slug = 'cynical-idealism-lillian-boxfish';
INSERT INTO writing_pieces
(id, owner_id, slug, title, subtitle, type, status, visibility, excerpt,
 structured_content, cover_image_id, created_at, updated_at, published_at,
 archived_at, show_origin, source_conversation_id)
VALUES (
  'wrt_3015cb6cf3f4f7fe0f33fd94d956a163','usr_ffbc49c36dc84f0889dfb5de2f68ccc3','cynical-idealism-lillian-boxfish','Cynical Idealism','Hybrid analytic/personal essay from high school','essay','public','public',
  'Humans are hopeful, but the reality is disappointing — or, in my words, cynical idealism.','{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "Cynical Idealism"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "High-school AP Literature hybrid essay responding to Lillian Boxfish Takes a Walk — personal reflection woven with close reading on hope, cynicism, and endurance.", "marks": [{"type": "italic"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Cynical Idealism"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ever since a certain day at age eleven, I have contemplated the question- is the human race inherently good or bad? It was a debate tournament amongst college students that later came to define my ideology, though at that moment it had simply piqued my interest to know that the winning side argued that it was bad, a resolution quite unlike what I had imagined. When I asked my dad for his position, his answer was somewhere along the lines of inherent evilness, and then laughed a little at the cynicism of his response. He paused for a moment, thinking a little, and gave me a peculiar answer- humans are hopeful, but the reality is disappointing. While I cannot remember his exact words now, the implications lived with me through the years, and as I grew up, I learned the struggle of having both hopefulness and realism, or in my words- cynical idealism, a hopefulness dulled by the real world, but a cynicism too optimistic about the future."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "I toy with the thought often, the juxtaposition of hope and hopelessness, and upon walking with Lillian Boxfish through her journey on New Year''s Eve, I was reminded of the oxymoronic concept of a cynical idealist. As a cynical idealist herself, Lillian Boxfish portrays a conflicted ideology morphed through the reality of sexism and city violence but also the hopes of interpersonal connection and love. Kathleen Rooney argues for a need for hope and gratitude in an often disappointing reality through utilizing characterization and her metaphoric approach of painting Lillian’s life as a circle, ending Boxfish’s conflict with herself with the same metaphor as the beginning."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Throughout the book, Rooney paints Boxfish as a character that often appears undecided to readers as to the way that she approaches her life. While certain in her resolve to never marry, she falls in love faithfully, and while certain in her hate of certain things, seems to love others quite similar to those that she hates. However, the reason behind her characterization does not appear until the readers dive further into the book. Her struggles with her career, mental health, and sexism bring out the full Boxfish as a hopeful realist relentlessly continuing in her journey despite the struggles that she faces. Upon her journey on New Year''s Eve, Boxfish revisits Delmonico’s to find a friendly family willing to ask her to sit with them. In their conversation, she describes, “the constant low-grade lunacy of life in the city--but I am surprised to find, and I think they are too, that our stories emphasize the serendipitous, even the magical. Our tone is that of conspirators, as though we are afraid to be overheard speaking fondly of a city that conventional wisdom declares beyond hope”(153). Here, Rooney uses the juxtaposition of diction choices to magnify both the “lunacy” and the “serendipitous” that is her life in the city. While their conversation begins with the negative, it gradually changes into a hopeful tone for a better future, a drastic change in connotation Boxfish herself seems to be equally surprised about. While she compares their conversation to conspiracies, a gesture at the commonly accepted realism, Rooney paints an upbeat mood to reflect the value of hopefulness in that commonly accepted pessimism. Here, the contrast between cynicism about the reality of the unsalvageable city versus the hopeful nature of her conspiracies brings out Rooney''s argument for the value of hopefulness during despair. Upon leaving Delmonico’s, Boxfish finds herself almost in tears from her connection with the family, and how much their kindness softened her scars of the past and quelled her loneliness. With such an implication, Rooney argues for the value of finding happiness and having hope and gratitude during the downs of life."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "In the last few pages of the book, we can further sense such a dynamic development of Boxfish’s mentality from her resolution with time and herself, admitting that “The future and I are just about even, our quarrel all but resolved. I welcome its coming, and I resolve to be attentive to the details of its arrival...waving as it comes into view, born toward the present on its road of anthracite” (284). Using personification to present her conflict with herself as her conflict with time, Boxfish looks back upon her life as a journey meant to be something greater than herself, an almost noble battle with an enemy she has learned to forgive. She reflects on all the negative things that she has ever experienced in her life and sums it up as one entire battle, which she is now past, and in turn, looks to the future with a new hopefulness despite her past struggles. Boxfish then hints at the end of her life in the future that is to come, bringing back the poetic symbol of the road of anthracite, a symbol presented in the very beginning of the book and representative of Boxfish’s life. Throughout her life, Boxfish has doubted her decisions, conscious of her differences, her critiques, and her fall from being the highest-paid advertising woman in the world, but in the end, when she finally expresses closure with herself, she finds that what she needed was her earliest, unwavering dream all along, and hopefulness for a future, no matter how short. By utilizing this form of structural callback, Rooney communicates the value of being gratuitous and hopeful through the worst of it all, because in the end, we would still come full circle in our journey in life, and that no matter what you do in life, it will all have been worth the struggle. Rooney glorifies the resolution, and the ups despite the downs, bringing Boxfish’s life full circle with a positive ending. With this artistic touch, she presents Boxfish’s entire life as an argument for remaining hopeful and gratuitous, making an example out of Boxfish’s seemingly downward spiral of life, but her remaining hope for her future. She makes a lesson out of the cynical idealism of Boxfish, and in turn inspires the readers to be hopeful during the lows of their lives."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Closing the book upon finishing the pages, I was hit face first with the implications that the adored cynical idealist represented in my life, and the debate that first introduced me to the concept of cynical idealism. While the concept had always existed, I had struggled to develop it further before I had encountered the complex characterization of Lillian Boxfish. I had always known myself to be cynically ideal, to marvel at kindness and sigh in disappointment at the world, and to dig myself out of emotional holes that I keep getting myself into. I recalled specifically the spring of my junior year when I was drowning in the stress that I put on myself while studying for my four AP tests. For almost two months I lacked sound sleep or a motivation to be joyous in school, repercussions of a mental burden too imminent to think clearly. I begged for the school year to end every day, and cried myself to sleep every other day. On the nights before each of my AP tests, I failed to sleep until four in the morning, when the birds had already begun to chirp and laugh at my lack of mental strength. Yet I had won my battle, though I could’ve easily canceled my AP tests as I had wished to do every day of those two dreadful months. Boxfish’s story gave me insight into how I managed to do it, and hints as to how I might avoid such a struggle again, which is to retain hope for a future, no matter how distant or near. While I don’t tell my friends this, I spent every single day of those two months praying, though I was all but religious before that. I meditated and sought intellectual clearance. I had my eyes on very foreseeable freedom, right when I finished my AP tests, and I looked forward to it daily. I still struggle with balancing my education and my mental health in my senior year. However, a hope for a brighter future in college and in life carries me forward, and I hope that they shall continue to be my motivation as I move forward in life. My past burdens of balancing stressors are behind me, though I still have a whole life ahead full of as much joy as stress. Knowing now that my struggles are, as Rooney implies, but a small part of the battle, I have already learned to let go of some of my burdens, seeing as I no longer spend all my free time locking myself up and studying my weekends away, trapping myself in the lows of my emotional health. I cannot say I was very bright and hopeful then or now, but my lingering hopes as a cynical idealist propels me forward, and it gives me the motivation to make the world better. As a cynical idealist, I often feel the swinging mood of a pendulum, but then I remember that humans are inherently bad to begin with, as per the ending decision from the famous debate. However, the fact that there is happiness and kindness in the world means that people are trying to make the world a brighter place, that they are purposefully being bright and welcoming, hopeful and gratuitous. While I will leave high school for a university soon, I strive to bring as much passion into my life as I can, although I have a right to be pessimistic sometimes, because that is the reality of a cynical idealist."}]}]}',NULL,1785481355305,1785481355305,1785481355305,NULL,0,NULL
);
